export function Playlist({
  layout = "{{layout}}",
  accent = "{{accent}}",
  showDuration = {{showDuration}},
  showArt = {{showArt}},
}) {
  const compact = layout === "compact";
  const tracks = [
    { title: "Slow Static", duration: "3:12", now: true },
    { title: "Amber Fields", duration: "4:05", now: false },
    { title: "Quiet Harbour", duration: "2:47", now: false },
  ];
  return (
    <ul style={{ listStyle: "none", margin: 0, padding: 0, maxWidth: 340, font: "14px/1.4 system-ui, sans-serif",
      color: "#241430", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden" }}>
      {tracks.map((track, i) => (
        <li key={track.title} style={{ display: "flex", alignItems: "center", gap: 10,
          padding: compact ? "7px 12px" : "12px 14px",
          borderBottom: i < tracks.length - 1 ? "1px solid #24143014" : "none",
          background: track.now ? "#24143010" : "transparent",
          borderLeft: track.now ? `3px solid ${accent}` : "3px solid transparent" }}>
          {showArt && (
            <span style={{ width: compact ? 20 : 28, height: compact ? 20 : 28, borderRadius: 6,
              background: "linear-gradient(135deg,#BFD9F2,#D9C8F0)", flex: "none" }} aria-hidden="true" />
          )}
          <span style={{ display: "flex", flexDirection: "column", flex: 1, minWidth: 0 }}>
            <span style={{ fontWeight: 600, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              {track.title}
            </span>
            {track.now && (
              <span style={{ fontSize: 11, fontWeight: 600, color: accent }} aria-hidden="true">Now playing</span>
            )}
          </span>
          {showDuration && <span style={{ fontSize: 12, color: "#24143099", flex: "none" }}>{track.duration}</span>}
        </li>
      ))}
    </ul>
  );
}
